  "city.doppel-parlor.description": "Ein Salon neben Doppels Zentralem Forschungslabor. Gäste werden gesetzt und erhalten die Forschungstagebücher Seite für Seite.",
  "city.doppel-lab.description": "Das innere Forschungsinstitut tief im Forschungslabor von Doppel. Hier sammeln sich die Tagebücher der Forschenden, die einst nach Eternal entsandt wurden.",
  "city.doppel-lab.displayName": "Doppel · Inneres Forschungsinstitut",
  "city.doppel-office.description": "Doppels Verwaltungsabteilung, die Forschungsergebnisse und den Einsatz der Relikte erfasst. Freigaben durchlaufen viele Stufen, daher dauert das Warten lange.",
  "city.doppel-office.displayName": "Doppel · Verwaltungsabteilung",
  "city.rust-garage.description": "Rusts Wartungshalle. Aufträge zur Reparatur defekter Forschungsgeräte reißen nicht ab.",
  "city.rust-garage.displayName": "Rust · Wartungshalle",
  "city.rust-lease.description": "Rusts Mietverwaltung, die Hochleistungsgeräte verleiht. Schon eine einzige Verlängerung zieht lange Verhandlungen nach sich.",
  "city.rust-lease.displayName": "Rust · Mietverwaltung",
  "city.doppel-upper.description": "Das oberste Stockwerk des Forschungslabors von Doppel. Hier sitzen jene, die den Zweck der Forschung bestimmen.",
  "city.doppel-upper.displayName": "Doppel · Oberste Führung",
  "city.rust-works.description": "Eine riesige Gießerei im Herzen von Rust. Entwurf und Reparatur der Forschungsgeräte laufen an einem Ort zusammen.",
  "city.rust-works.displayName": "Rust · Zentrale Gießerei",
  "city.odidi-embassy.description": "Der Empfangsraum, in dem Odidi, die Stadt der Traumforschung, externe Gäste empfängt. Die Vorschläge kommen stets zuerst von ihnen.",
  "city.odidi-embassy.displayName": "Odidi · Diplomatischer Empfangsraum",
  "journal.interaction-doppel-lab-01.title": "Tagebuch der nicht heimgekehrten Entsendung",
  "journal.interaction-doppel-lab-01.body": "Das Tagebuch eines Forschenden, der nach Eternal entsandt wurde. Die letzte Seite besteht aus einer einzigen Zeile: „Die Ablösung ist eingetroffen“, und das Unterschriftsfeld darunter ist leer.",
  "city.department.exchange": "Tauschstelle",
  "city.department.council": "Rat",
  "city.doppel-parlor.displayName": "Doppel · Salon des Zentralen Forschungslabors",
  "shopClerk.obi.name": "Obi",
  "shopClerk.protia.name": "Protia",
  "shopClerk.haine.name": "Haine",
  "journal.interaction-doppel-01.title": "Das Schild des Blauen Korridors",
  "journal.interaction-doppel-01.body": "Die erste Anschlagtafel des Gewächshauses bittet noch immer darum, restaurierte Körper als neue Nachbarn willkommen zu heißen, nicht als Schauobjekt.",
  "journal.interaction-doppel-02.title": "Der Gruß, der sich wiederholt",
  "bond.torika.0": "Wer bist du?",
  "bond.torika.1": "Du bist wieder da.",
  "bond.torika.2": "Du darfst bei mir bleiben.",
  "bond.torika.3": "Was machen wir heute?",
  "bond.torika.4": "Ich kenne deine Schritte.",
  "bond.torika.5": "Wenn wir zusammen sind, ist es ruhig.",
  "bond.torika.6": "Ich halte dir den Rücken frei.",
  "bond.torika.7": "Ich habe gewartet.",
  "bond.torika.8": "Wenn du kommst, fühle ich mich sicher.",
  "bond.torika.9": "Ich gehe mit dir bis zum Ende.",
  "bond.torika.10": "Unseren Garten beschütze ich selbst.",
  "bond.rex.0": "Fass mich nicht an.",
  "bond.rex.1": "Hast du keine Angst?",
  "bond.rex.2": "Ein bisschen interessant.",
  "bond.rex.3": "Komm auch zur nächsten Jagd.",
  "bond.rex.4": "Ich kenne deinen Geruch jetzt.",
  "bond.rex.5": "Weich nicht von meiner Seite.",
  "bond.rex.6": "Was auf dich losgeht, beiße ich.",
  "bond.rex.7": "Heute wieder zu spät.",
  "bond.rex.8": "Deine Stimme ist mir lieber als Befehle.",
  "bond.rex.9": "Du bist mein einziges Rudel.",
  "bond.rex.10": "Ich stehe für immer auf deiner Seite.",
  "bond.spino.0": "…Was ist?",
  "bond.spino.1": "Ich vermisse das Wasser.",
  "bond.spino.2": "Es ist okay, still zu sein.",
  "bond.spino.3": "Erzähl mir mehr von dir.",
  "bond.spino.4": "Die Wellen sind heute ruhig.",
  "bond.spino.5": "Ich gehe gern mit dir spazieren.",
  "bond.spino.6": "Wenn es gefährlich wird, geh hinter mich.",
  "bond.spino.7": "Ich wusste, dass du kommst.",
  "bond.spino.8": "Ich habe mich an diese Stadt gewöhnt.",
  "bond.spino.9": "Deine Seite ist mein Wasser.",
  "bond.spino.10": "Lass uns zusammen überallhin fließen.",
  "bond.generic.0": "Es ist noch etwas ungewohnt.",
  "bond.generic.1": "Wir sehen uns heute wieder.",
  "bond.generic.2": "Ich gewöhne mich nach und nach daran.",
  "bond.generic.3": "Lass uns gemeinsam auf Mission gehen.",
  "bond.generic.4": "Ich freue mich, wenn du kommst.",
  "bond.generic.5": "Du darfst bei mir bleiben.",
  "bond.generic.6": "Auch diesmal helfe ich.",
  "bond.generic.7": "Ich habe gewartet.",
  "bond.generic.8": "Wir sind gute Gefährten.",
  "bond.generic.9": "Ich möchte lange mit dir zusammen sein.",
  "bond.generic.10": "Ab jetzt zähle ich auf dich.",
