  "relic.raitia-grass.name": "Viria",
  "relic.raitia-grass.origin": "Bilch",
  "relic.raitia-grass.excavationSite": "Karsthöhlensediment, Slowenien",
  "relic.raitia-grass.fossilRecord": "Aus einer einzigen Schicht Höhlensediment wurden Dutzende Schädel derselben Art geborgen. Fünf davon stimmen in Größe und Gebiss so genau überein, dass sie als ein Wurf eingestuft wurden.",
  "relic.raitia-grass.catalogSummary": "Ein Exemplar auf Bilchbasis, restauriert mit übergroßen Schneidezähnen und Backentaschen.",
  "relic.raitia-grass.squadNote": "Die entbehrliche Masse der Vernichtung. Sie strömen alle zugleich in die gewiesene Richtung und füllen den Gang; die hinteren treten geradewegs über die Stelle, an der die vorderen fielen.",
  "relic.raitia-grass.researcherTitle": "Forscher",
  "relic.raitia-grass.unlockRecord": "Identifikationsprotokoll 207. Als zugehörig zur Vernichtung bestätigt. Unter den fünf in Kapuzenpyjamas mit Mäuseohren trägt dieses Exemplar einen grünen Knoten; auffallend sind die käseförmige Tasche, die bezahnten Pantoffeln und der gestreifte Schwanz mit einer Schleife an der Spitze. Fand es Futter, meldete es das nicht mit einem Laut, sondern mit dem Geräusch seiner Schneidezähne, und die Schwestern, die es hörten, schwärmten sofort an dieselbe Stelle. Wo es nagte, lagen frische Triebe verstreut, und in jedem Fußabdruck seines Weges keimten Samen, sodass ein grüner Pfad zurückblieb. Warum es selbst zur Zeit des Winterschlafs nicht aufhört zu fressen, wurde nicht bestätigt.",
  "relic.raitia-grass.observation.originYear": "Vor etwa 2 Millionen Jahren",
  "relic.raitia-grass.observation.restorationYear": "E.C. 2",
  "relic.raitia-grass.observation.lifeStage": "Jungtier",
  "relic.raitia-grass.observation.height": "0,94 m",
  "relic.raitia-grass.observation.weight": "21 kg",
  "relic.raitia-grass.passive.name": "Winterschlaf",
  "relic.raitia-grass.passive.desc": "Einmal pro Kampf stellt sie, wenn ihre LP auf die Hälfte oder darunter fallen, 5 Sekunden lang jede Sekunde 3 % der max. LP wieder her.",
  "relic.raitia-grass.ferocity.name": "Völlerei",
  "relic.raitia-grass.basic.name": "Schneidezahnnagen",
  "relic.raitia-grass.ultimate.name": "Backentaschen-Ausschüttung",
  "relic.raitia-grass.projectName": "ANNIHILATION SWARM — Überfütterte Population",
  "relic.raitia-water.name": "Guttia",
  "relic.raitia-water.origin": "Bilch",
  "relic.raitia-water.excavationSite": "Karsthöhlensediment, Slowenien",
  "relic.raitia-water.fossilRecord": "Aus einer einzigen Schicht Höhlensediment wurden Dutzende Schädel derselben Art geborgen. Fünf davon stimmen in Größe und Gebiss so genau überein, dass sie als ein Wurf eingestuft wurden.",
  "relic.raitia-water.catalogSummary": "Ein Exemplar auf Bilchbasis, restauriert mit übergroßen Schneidezähnen und Backentaschen.",
  "relic.raitia-water.squadNote": "Die entbehrliche Masse der Vernichtung. Sie strömen alle zugleich in die gewiesene Richtung und füllen den Gang; die hinteren treten geradewegs über die Stelle, an der die vorderen fielen.",
  "relic.raitia-water.researcherTitle": "Forscher",
  "relic.raitia-water.unlockRecord": "Identifikationsprotokoll 208. Als zugehörig zur Vernichtung bestätigt. Unter denen im gleichen Kapuzenpyjama hat dieses Exemplar einen blau gestreiften Schwanz mit einem Wattebausch an der Spitze und lächelt, eine Hand in die Hüfte gestemmt, die Finger der anderen am Mundwinkel. Hörte es das Geräusch der Schneidezähne einer Schwester, lief es lächelnd als Erstes los, und nahe angekommen nagte es zuerst an der Ausrüstung, die in Reichweite lag. Wo das Rudel vorbeigezogen war, zog sich eine lange Spur nasser Fußabdrücke. Was diese Abdrücke befeuchtet, wurde nicht bestätigt.",
  "relic.raitia-water.observation.originYear": "Vor etwa 2 Millionen Jahren",
  "relic.raitia-water.observation.restorationYear": "E.C. 2",
  "relic.raitia-water.observation.lifeStage": "Jungtier",
  "relic.raitia-water.observation.height": "0,94 m",
  "relic.raitia-water.observation.weight": "21 kg",
  "relic.raitia-water.passive.name": "Winterschlaf",
  "relic.raitia-water.passive.desc": "Einmal pro Kampf stellt sie, wenn ihre LP auf die Hälfte oder darunter fallen, 5 Sekunden lang jede Sekunde 3 % der max. LP wieder her.",
  "relic.raitia-water.ferocity.name": "Völlerei",
  "relic.raitia-water.basic.name": "Schneidezahnnagen",
  "relic.raitia-water.ultimate.name": "Backentaschen-Ausschüttung",
  "relic.raitia-water.projectName": "ANNIHILATION SWARM — Überfütterte Population",
  "relic.raitia-fire.name": "Favia",
  "relic.raitia-fire.origin": "Bilch",
  "relic.raitia-fire.excavationSite": "Karsthöhlensediment, Slowenien",
  "relic.raitia-fire.fossilRecord": "Aus einer einzigen Schicht Höhlensediment wurden Dutzende Schädel derselben Art geborgen. Fünf davon stimmen in Größe und Gebiss so genau überein, dass sie als ein Wurf eingestuft wurden.",
  "relic.raitia-fire.catalogSummary": "Ein Exemplar auf Bilchbasis, restauriert mit übergroßen Schneidezähnen und Backentaschen.",
  "relic.raitia-fire.squadNote": "Die entbehrliche Masse der Vernichtung. Sie strömen alle zugleich in die gewiesene Richtung und füllen den Gang; die hinteren treten geradewegs über die Stelle, an der die vorderen fielen.",
  "relic.raitia-fire.researcherTitle": "Forscher",
  "relic.raitia-fire.unlockRecord": "Identifikationsprotokoll 209. Als zugehörig zur Vernichtung bestätigt. Unter denen im gleichen Kapuzenpyjama trägt dieses Exemplar eine rosa karierte Schleife und steht mit halb wachem Gesicht da, eine Hand reibt sich die Augen, die andere ist in die Hüfte gestemmt. Obwohl es schläfrig wirkte, hörte es nicht auf zu fressen und nagte mit den Schneidezähnen weiter, auch als die Backentaschen voll waren. Stürmten die Schwestern los, folgte es ihnen und rieb sich dabei die Augen. Ob die Schläfrigkeit gespielt oder echt ist, wurde nicht bestätigt.",
  "relic.raitia-fire.observation.originYear": "Vor etwa 2 Millionen Jahren",
  "relic.raitia-fire.observation.restorationYear": "E.C. 2",
  "relic.raitia-fire.observation.lifeStage": "Jungtier",
  "relic.raitia-fire.observation.height": "0,94 m",
  "relic.raitia-fire.observation.weight": "21 kg",
  "relic.raitia-fire.passive.name": "Winterschlaf",
  "relic.raitia-fire.passive.desc": "Einmal pro Kampf stellt sie, wenn ihre LP auf die Hälfte oder darunter fallen, 5 Sekunden lang jede Sekunde 3 % der max. LP wieder her.",
  "relic.raitia-fire.ferocity.name": "Völlerei",
  "relic.raitia-fire.basic.name": "Schneidezahnnagen",
  "relic.raitia-fire.ultimate.name": "Backentaschen-Ausschüttung",
