  "relic.raitia-earth.name": "Silia",
  "relic.raitia-earth.origin": "Bilch",
  "relic.raitia-earth.excavationSite": "Karsthöhlensediment, Slowenien",
  "relic.raitia-earth.fossilRecord": "Aus einer einzigen Schicht Höhlensediment wurden Dutzende Schädel derselben Art geborgen. Fünf davon stimmen in Größe und Gebiss so genau überein, dass sie als ein Wurf eingestuft wurden.",
  "relic.raitia-earth.catalogSummary": "Ein Exemplar auf Bilchbasis, restauriert mit übergroßen Schneidezähnen und Backentaschen.",
  "relic.raitia-earth.squadNote": "Die entbehrliche Masse der Vernichtung. Sie strömen alle zugleich in die gewiesene Richtung und füllen den Gang; die hinteren treten geradewegs über die Stelle, an der die vorderen fielen.",
  "relic.raitia-earth.researcherTitle": "Forscher",
  "relic.raitia-earth.unlockRecord": "Identifikationsprotokoll 210. Als zugehörig zur Vernichtung bestätigt. Unter denen im gleichen Kapuzenpyjama fällt dieses Exemplar durch braunen Grund, gelben Knoten und geflochtenes Haar auf und trägt einen großen Fellbüschel an der Schwanzspitze. Stand es mit nach vorn ausgestreckten Händen da, strömten die Schwestern alle gleichzeitig in Richtung seiner Fingerspitzen, und wo die vordere gefallen war, stieg die hintere einfach darüber hinweg. Wer die Richtung seiner Fingerspitzen bestimmt, wurde nicht bestätigt.",
  "relic.raitia-earth.observation.originYear": "Vor etwa 2 Millionen Jahren",
  "relic.raitia-earth.observation.restorationYear": "E.C. 2",
  "relic.raitia-earth.observation.lifeStage": "Jungtier",
  "relic.raitia-earth.observation.height": "0,94 m",
  "relic.raitia-earth.observation.weight": "21 kg",
  "relic.raitia-earth.passive.name": "Winterschlaf",
  "relic.raitia-earth.passive.desc": "Einmal pro Kampf stellt sie, wenn ihre LP auf die Hälfte oder darunter fallen, 5 Sekunden lang jede Sekunde 3 % der max. LP wieder her.",
  "relic.raitia-earth.ferocity.name": "Völlerei",
  "relic.raitia-earth.basic.name": "Schneidezahnnagen",
  "relic.raitia-earth.ultimate.name": "Backentaschen-Ausschüttung",
  "relic.raitia-earth.projectName": "ANNIHILATION SWARM — Überfütterte Population",
  "relic.raitia-wind.name": "Ventia",
  "relic.raitia-wind.origin": "Bilch",
  "relic.raitia-wind.excavationSite": "Karsthöhlensediment, Slowenien",
  "relic.raitia-wind.fossilRecord": "Aus einer einzigen Schicht Höhlensediment wurden Dutzende Schädel derselben Art geborgen. Fünf davon stimmen in Größe und Gebiss so genau überein, dass sie als ein Wurf eingestuft wurden.",
  "relic.raitia-wind.catalogSummary": "Ein Exemplar auf Bilchbasis, restauriert mit übergroßen Schneidezähnen und Backentaschen.",
  "relic.raitia-wind.squadNote": "Die entbehrliche Masse der Vernichtung. Sie strömen alle zugleich in die gewiesene Richtung und füllen den Gang; die hinteren treten geradewegs über die Stelle, an der die vorderen fielen.",
  "relic.raitia-wind.researcherTitle": "Forscher",
  "relic.raitia-wind.unlockRecord": "Identifikationsprotokoll 211. Als der Vernichtung zugehörig bestätigt. Es ist das Exemplar mit der mintfarbenen Schleife unter den Schwestern im gleichen Kapuzenschlafanzug; sie steht mit verschränkten Armen und fest geschlossenem Mund da. Sie folgte erst widerwillig, nachdem ihre Schwestern zum Futter gestürmt waren, nagte dort aber am längsten mit den Schneidezähnen. Dass sie mit dem Geräusch der Schneidezähne je etwas mitgeteilt hätte, wurde kein einziges Mal festgestellt.",
  "relic.raitia-wind.observation.originYear": "Vor etwa 2 Millionen Jahren",
  "relic.raitia-wind.observation.restorationYear": "E.C. 2",
  "relic.raitia-wind.observation.lifeStage": "Jungtier",
  "relic.raitia-wind.observation.height": "0,94 m",
  "relic.raitia-wind.observation.weight": "21 kg",
